"use strict";

const KeyValueAdapter = require("../functions/adapterStore.js");

/**
 * Firebase Realtime Database adapter for CroxyDB.
 * @module adapters/firebase
 */

/**
 * @typedef {Object} FirebaseDBOptions
 * @property {string} [url] Firebase Realtime Database URL.
 * @property {string} [databaseURL] Firebase Realtime Database URL.
 * @property {string} [path="croxydb"] Base path used by CroxyDB.
 * @property {string} [ref] Alias of path.
 * @property {Object} [app] Existing firebase-admin app.
 * @property {Object} [admin] Existing firebase-admin module.
 * @property {Object} [database] Existing Firebase database instance.
 * @property {Object} [credential] firebase-admin credential.
 * @property {Object} [serviceAccount] Service account object used with credential.cert.
 * @property {string} [seperator="."] Nested-key separator.
 */

function encodeKey(key) {
  return encodeURIComponent(key).replace(/\./g, "%2E");
}

/**
 * Stores CroxyDB values under a Firebase Realtime Database path.
 * @class
 * @extends KeyValueAdapter
 */
class FirebaseDB extends KeyValueAdapter {
  /**
   * Creates a Firebase adapter.
   * @param {FirebaseDBOptions} [options={}] Adapter options.
   */
  constructor(options = {}) {
    super(options);
    this.options = options;
    this.basePath = options.path || options.ref || options.dbName || "croxydb";
    this.admin = options.admin || null;
    this.database = options.database || null;
    this.ready = false;
  }

  /**
   * Initializes firebase-admin and the database reference when needed.
   * @returns {Promise<void>}
   */
  async init() {
    if (this.ready) return;

    if (!this.database) {
      if (!this.admin) {
        try {
          this.admin = require("firebase-admin");
        } catch (error) {
          throw new TypeError("You must install \"firebase-admin\" module to use the Firebase adapter.");
        }
      }

      const app = this.options.app || this.admin.apps[0] || this.admin.initializeApp({
        credential: this.options.credential || (this.options.serviceAccount ? this.admin.credential.cert(this.options.serviceAccount) : this.admin.credential.applicationDefault()),
        databaseURL: this.options.databaseURL || this.options.url
      });

      this.database = app.database();
    }

    this.ready = true;
  }

  /**
   * Builds a Firebase reference for a root key.
   * @param {string} key Root key.
   * @returns {Object}
   */
  ref(key) {
    return this.database.ref(`${this.basePath}/${encodeKey(key)}`);
  }

  /**
   * Reads a root key from Firebase.
   * @param {string} key Root key.
   * @returns {Promise<*>}
   */
  async readValue(key) {
    await this.init();
    const snapshot = await this.ref(key).once("value");
    return snapshot.exists() ? snapshot.val() : undefined;
  }

  /**
   * Writes a root key to Firebase.
   * @param {string} key Root key.
   * @param {*} value Value to write.
   * @returns {Promise<void>}
   */
  async writeValue(key, value) {
    await this.init();
    await this.ref(key).set(value);
  }

  /**
   * Deletes a root key from Firebase.
   * @param {string} key Root key.
   * @returns {Promise<void>}
   */
  async deleteValue(key) {
    await this.init();
    await this.ref(key).remove();
  }

  /**
   * Reads all root keys from Firebase.
   * @returns {Promise<Object>}
   */
  async readAllValues() {
    await this.init();
    const snapshot = await this.database.ref(this.basePath).once("value");
    const raw = snapshot.exists() ? snapshot.val() : {};
    const result = {};
    Object.keys(raw || {}).forEach((key) => {
      result[decodeURIComponent(key)] = raw[key];
    });
    return result;
  }

  /**
   * Clears all data under the Firebase base path.
   * @returns {Promise<void>}
   */
  async clearValues() {
    await this.init();
    await this.database.ref(this.basePath).remove();
  }
}

module.exports = FirebaseDB;
